// Stand-in Sentry server: logs each envelope's item types and any session status.
const http = require('http');
const fs = require('fs');
const out = 'C:\\guitest\\exitcrash\\sink.txt';
http.createServer((req, res) => {
  const chunks = [];
  req.on('data', c => chunks.push(c));
  req.on('end', () => {
    const body = Buffer.concat(chunks).toString('utf8');
    const lines = body.split('\n');
    const items = [];
    for (let i = 1; i < lines.length; i++) {
      try {
        const h = JSON.parse(lines[i]);
        if (h && h.type) {
          let detail = '';
          if (h.type === 'session') {
            try { const s = JSON.parse(lines[i + 1]); detail = ` status=${s.status} errors=${s.errors}`; } catch (e) {}
          }
          items.push(h.type + detail);
        }
      } catch (e) {}
    }
    fs.appendFileSync(out, `${new Date().toISOString()} ${req.method} ${req.url} ${body.length}B items=[${items.join('; ')}]\n`);
    res.writeHead(200, {'Content-Type': 'application/json'});
    res.end('{}');
  });
}).listen(8799, '127.0.0.1');

